<script setup>
import { onMounted, ref } from 'vue'
import { useBudgetTaxStore } from '@/stores/budgetTaxStore.js'
const props = defineProps({ idBudget: { type: [String, Number], required: true } }); const store = useBudgetTaxStore(); const regimeA = ref('ordinary'); const regimeB = ref('simple')
async function load() { await store.compare(props.idBudget, regimeA.value, regimeB.value) }; onMounted(load)
const rows = [['taxable_base','Base gravable'],['tax_caused','Impuesto causado'],['advances','Anticipos'],['withholdings','Retenciones'],['payable_balance','Saldo a pagar'],['annual_total','Total anual'],['effective_rate','Tasa efectiva']]
</script>
<template><section class="tax-card"><div class="tax-section-heading"><div><span class="eyebrow">Decisión de régimen</span><h2>Comparar escenarios</h2></div><button class="btn btn-secondary" @click="load">Actualizar comparación</button></div><div class="compare-controls"><label>Configuración A<select v-model="regimeA"><option value="ordinary">Ordinario</option><option value="simple">SIMPLE</option></select></label><label>Configuración B<select v-model="regimeB"><option value="simple">SIMPLE</option><option value="ordinary">Ordinario</option></select></label></div><div v-if="!store.comparison" class="tax-empty">Selecciona las configuraciones para consultar el comparador.</div><div v-else class="table-wrap"><table class="crm-table"><thead><tr><th>Indicador</th><th>Ordinario</th><th>SIMPLE</th><th>Diferencia</th></tr></thead><tbody><tr v-for="row in rows" :key="row[0]"><td>{{ row[1] }}</td><td>{{ store.comparison.ordinary?.[row[0]] ?? 'Sin configurar' }}</td><td>{{ store.comparison.simple?.[row[0]] ?? 'Sin configurar' }}</td><td>{{ store.comparison.difference?.[row[0]] ?? '—' }}</td></tr></tbody></table></div><div class="tax-warning"><strong>Impacto en caja</strong><span>Un mismo total anual puede tener un flujo mensual diferente. Revisa anticipos, declaraciones y pagos antes de decidir.</span></div></section></template>
